func newImporter(t *testing.T) *Importer {
	t.Helper()
	s, err := store.OpenMemory(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { s.Close() })
	return &Importer{Store: s, RawDir: filepath.Join(t.TempDir(), "raw")}
}

func TestImportReaderCreatesActivity(t *testing.T) {
	ctx := context.Background()
	im := newImporter(t)
	res := im.ImportReader(ctx, bytes.NewReader(fittest.Encode(t, fittest.Default())), "upload:ride.fit")
	if res.Status != store.Created || res.Error != "" || res.ActivityID == 0 {
		t.Fatalf("result %+v", res)
	}

	a, err := im.Store.Get(ctx, res.ActivityID)
	if err != nil {
		t.Fatal(err)
	}
	if a.Sport != "cycling" || a.DistanceM != 480 || a.TZOffsetS != 7200 || a.AvgHR != 120 || a.AnalysisVersion != AnalysisVersion {
		t.Errorf("activity %+v", a)
	}

	blob, err := im.Store.Stream(ctx, res.ActivityID)
	if err != nil {
		t.Fatal(err)
	}
	st, err := DecodeStream(blob)
	if err != nil {
		t.Fatal(err)
	}
	if st.Len() != 60 || st.HR[10] != 120 || math.Abs(st.Lat[0]-48.2) > 1e-6 {
		t.Errorf("stream len=%d hr=%v lat=%v", st.Len(), st.HR[10], st.Lat[0])
	}

	// A straight line north collapses to its end points.
	track, err := im.Store.Track(ctx, res.ActivityID)
	if err != nil || track.Points != 2 {
		t.Errorf("track %+v %v", track, err)
	}
}

func TestReimportIsIdempotent(t *testing.T) {
	ctx := context.Background()
	im := newImporter(t)
	raw := fittest.Encode(t, fittest.Default())
	first := im.ImportReader(ctx, bytes.NewReader(raw), "a.fit")
	second := im.ImportReader(ctx, bytes.NewReader(raw), "b.fit")
	if second.Status != store.Unchanged || second.ActivityID != first.ActivityID {
		t.Errorf("second import %+v", second)
	}
	// Same recording, different bytes (e.g. re-saved by another tool).
	changed := fittest.Default()
	changed.HROffset = 3
	third := im.ImportReader(ctx, bytes.NewReader(fittest.Encode(t, changed)), "c.fit")
	if third.Status != store.Updated || third.ActivityID != first.ActivityID {
		t.Errorf("third import %+v", third)
	}
	if n, _ := im.Store.Count(ctx); n != 1 {
		t.Errorf("count %d", n)
	}
	files, _ := filepath.Glob(filepath.Join(im.RawDir, "*", "*.fit"))
	if len(files) != 2 {
		t.Errorf("raw archive has %d files, want 2 (one per distinct content)", len(files))
	}
}

func TestIndoorActivityHasNoTrack(t *testing.T) {
	ctx := context.Background()
	im := newImporter(t)
	o := fittest.Default()
	o.WithGPS = false
	res := im.ImportReader(ctx, bytes.NewReader(fittest.Encode(t, o)), "indoor.fit")
	if res.Status != store.Created {
		t.Fatalf("result %+v", res)
	}
	if _, err := im.Store.Track(ctx, res.ActivityID); err == nil {
		t.Error("indoor activity must not have a track")
	}
}

